214	    /**
215	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
216	     * stripped. When a leading {@code '+'} and country code are present they are kept;
217	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
218	     * is dropped from the national digits. The result must be a {@code '+'} followed
219	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
220	     * is returned to signal a bad request.
221	     */
222	    /**
223	     * Build the customer code for a newly created owner, formatted
224	     * {@code '<LAST3>-<NNNN>'} where {@code LAST3} is the upper-cased first three
225	     * letters of the last name and {@code NNNN} is a global 4-digit zero-padded
226	     * sequence equal to one more than the current number of owners.
227	     */
228	    private String nextCustomerCode(String lastName) {
229	        String prefix = lastName == null ? "" : lastName;
230	        prefix = prefix.substring(0, Math.min(3, prefix.length())).toUpperCase(Locale.ROOT);
231	        int sequence = this.clinicService.findAllOwners().size() + 1;
232	        return String.format("%s-%04d", prefix, sequence);
233	    }
234	
235	    /**
236	     * Determine whether another owner already belongs to the same household, i.e. shares
237	     * both the given last name and address. Both fields are compared case-insensitively
238	     * after collapsing runs of whitespace to a single space and trimming the ends.
239	     */
240	    private boolean isHouseholdDuplicate(String lastName, String address) {
241	        String normalizedLastName = normalizeForHousehold(lastName);
242	        String normalizedAddress = normalizeForHousehold(address);
243	        return this.clinicService.findAllOwners().stream()
244	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
245	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress));
246	    }
247	
248	    private String normalizeForHousehold(String value) {
249	        if (value == null) {
250	            return "";
251	        }
252	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
253	    }
254	
255	    private String normalizeTelephone(String telephone) {
256	        if (telephone == null) {
257	            return null;
258	        }
259	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
260	        String digits;
261	        if (cleaned.startsWith("+")) {
262	            digits = cleaned.substring(1);
263	        } else {
264	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
265	            digits = "61" + national;
266	        }
267	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
268	    }
